-- ===================================================================================
-- DYNAMIC CAMPAIGN REPORTER (generated by BriefingRoom)
-- Writes the state of every objective to dcs.log, so the result can be uploaded
-- back to BriefingRoom to advance the dynamic campaign. Line format:
-- BRDC|token|sequence|missionTime|missionComplete|playerAircraftLost|dead/total/complete/siteDead/siteTotal,...|W:category=used;...|L:type=lost;...
-- followed by the debrief of the same report, as JSON:
-- BRDCS|token|sequence|{"pilots":[...],"events":[...],"airDefenseKills":[...]}
-- Weapons used and aircraft lost are counted for the player's groups (player and AI wingmen).
-- The site of an objective is every unit of the groups of its targets (SAM site: launchers too).
-- ===================================================================================

briefingRoom.dynamicCampaign = { }
briefingRoom.dynamicCampaign.token = "$TOKEN$"
briefingRoom.dynamicCampaign.radarsDown = $RADARSDOWN$ -- campaign target SAM site with its radars destroyed
briefingRoom.dynamicCampaign.sequence = 0
briefingRoom.dynamicCampaign.dead = { } -- unit names reported dead by events
briefingRoom.dynamicCampaign.tracked = { } -- unit names that existed at mission start
-- Objective targets and sites as they were at mission start: the objective triggers
-- remove destroyed units from objective.unitNames, so they cannot be counted from there
briefingRoom.dynamicCampaign.objectiveUnits = { } -- objective index -> unit names
briefingRoom.dynamicCampaign.siteUnits = { } -- objective index -> unit names
briefingRoom.dynamicCampaign.siteNames = { } -- every site unit name
briefingRoom.dynamicCampaign.removed = { } -- radars removed at start (radarsDown)
briefingRoom.dynamicCampaign.samUnits = { } -- other enemy medium/long range SAM units: name -> { x, y, radar }
-- Debrief
briefingRoom.dynamicCampaign.pilots = { } -- key -> pilot stats
briefingRoom.dynamicCampaign.pilotOrder = { }
briefingRoom.dynamicCampaign.unitPilot = { } -- unit name -> pilot key (dead units have no player name)
briefingRoom.dynamicCampaign.lastHit = { } -- target unit name -> { pilot, weapon, target }
briefingRoom.dynamicCampaign.credited = { } -- target unit names already credited as a kill
briefingRoom.dynamicCampaign.hitWeapons = { } -- weapon ids already counted as a hit
briefingRoom.dynamicCampaign.events = { }
briefingRoom.dynamicCampaign.MAX_EVENTS = 300
briefingRoom.dynamicCampaign.playerLost = { } -- player aircraft lost (unit names)
briefingRoom.dynamicCampaign.playerLostCount = 0
briefingRoom.dynamicCampaign.flight = { } -- player group units: name -> { type, loaded = { category = count } }
briefingRoom.dynamicCampaign.stock = { $STOCK$ } -- weapons at the departure airbase
briefingRoom.dynamicCampaign.stockLabels = { $STOCKLABELS$ }
briefingRoom.dynamicCampaign.stockWarning = "$STOCKWARNING$"
briefingRoom.dynamicCampaign.stockWarned = false
briefingRoom.dynamicCampaign.tookOff = { }
briefingRoom.dynamicCampaign.endMissionLabel = "$ENDMISSIONLABEL$"

local function brdcSafeName(object)
  if object == nil then return nil end
  local ok, name = pcall(function() return object:getName() end)
  if ok then return name end
  return nil
end

local function brdcFindObject(name)
  local unit = Unit.getByName(name)
  if unit ~= nil then return unit end
  return StaticObject.getByName(name)
end

local function brdcIsDead(name)
  if briefingRoom.dynamicCampaign.dead[name] then return true end
  local object = brdcFindObject(name)
  if object == nil then return true end
  local ok, alive = pcall(function() return object:isExist() and object:getLife() >= 1 end)
  if not ok then return true end
  return not alive
end

-- Weapon category as tracked by the campaign stock, nil for guns and anything else
local function brdcWeaponCategory(desc)
  if desc == nil then return nil end
  if desc.category == Weapon.Category.MISSILE then
    if desc.missileCategory == Weapon.MissileCategory.AAM then return "AAM" end
    if desc.missileCategory == Weapon.MissileCategory.SAM then return nil end
    if desc.guidance == Weapon.GuidanceType.RADAR_PASSIVE then return "ARM" end
    return "AGM"
  end
  if desc.category == Weapon.Category.ROCKET then return "Rocket" end
  if desc.category == Weapon.Category.BOMB then
    if desc.guidance ~= nil and desc.guidance ~= 0 then return "GuidedBomb" end
    return "Bomb"
  end
  return nil
end

local function brdcCountWeapons(unit)
  local counts = { }
  if unit == nil then return counts end
  local ok, ammo = pcall(function() return unit:getAmmo() end)
  if not ok or ammo == nil then return counts end
  for _, entry in ipairs(ammo) do
    local category = brdcWeaponCategory(entry.desc)
    if category ~= nil then counts[category] = (counts[category] or 0) + (entry.count or 0) end
  end
  return counts
end

-- Snapshot of the weapons loaded by every unit of a player's group
local function brdcTrackFlight(playerUnit, overwrite)
  local dc = briefingRoom.dynamicCampaign
  local okGroup, group = pcall(function() return playerUnit:getGroup() end)
  if not okGroup or group == nil then return end
  for _, unit in ipairs(group:getUnits() or { }) do
    local name = brdcSafeName(unit)
    if name ~= nil and (overwrite or dc.flight[name] == nil) and not dc.playerLost[name] then
      local okType, typeName = pcall(function() return unit:getTypeName() end)
      dc.flight[name] = { type = okType and typeName or "unknown", loaded = brdcCountWeapons(unit) }
    end
  end
end

-- Warns once if the flight carries more than the departure airbase has
local function brdcCheckStock()
  local dc = briefingRoom.dynamicCampaign
  if dc.stockWarned then return end
  local loaded = { }
  for _, unitData in pairs(dc.flight) do
    for category, count in pairs(unitData.loaded) do loaded[category] = (loaded[category] or 0) + count end
  end
  local excess = { }
  for category, count in pairs(loaded) do
    if dc.stock[category] ~= nil and count > dc.stock[category] then
      table.insert(excess, (dc.stockLabels[category] or category).." "..count.."/"..dc.stock[category])
    end
  end
  if #excess > 0 then
    dc.stockWarned = true
    trigger.action.outTextForCoalition(briefingRoom.playerCoalition, dc.stockWarning.." "..table.concat(excess, ", "), 20)
  end
end

local function brdcFlightText()
  local dc = briefingRoom.dynamicCampaign
  local used = { }
  local lost = { }
  for name, unitData in pairs(dc.flight) do
    local remaining = { }
    local unit = Unit.getByName(name)
    local alive = not dc.playerLost[name] and unit ~= nil and not brdcIsDead(name)
    if alive then remaining = brdcCountWeapons(unit) else lost[unitData.type] = (lost[unitData.type] or 0) + 1 end
    for category, count in pairs(unitData.loaded) do
      local spent = count - (remaining[category] or 0)
      if spent > 0 then used[category] = (used[category] or 0) + spent end
    end
  end
  local usedText = { }
  for category, count in pairs(used) do table.insert(usedText, category.."="..count) end
  local lostText = { }
  for typeName, count in pairs(lost) do table.insert(lostText, typeName.."="..count) end
  return "|W:"..table.concat(usedText, ";").."|L:"..table.concat(lostText, ";")
end

-- ---------------------------------------------------------------- JSON (debrief line)

local function brdcJsonString(text)
  local escaped = string.gsub(tostring(text), '[%c"\\]', function(c)
    if c == '"' then return '\\"' end
    if c == '\\' then return '\\\\' end
    return string.format("\\u%04x", string.byte(c))
  end)
  return '"'..escaped..'"'
end

-- Tables with a first element or no element at all are arrays, others objects
local function brdcJson(value)
  local kind = type(value)
  if kind == "string" then return brdcJsonString(value) end
  if kind == "number" then
    if value ~= value or value == math.huge or value == -math.huge then return "0" end
    if value == math.floor(value) then return string.format("%.0f", value) end
    return string.format("%.3f", value)
  end
  if kind == "boolean" then return value and "true" or "false" end
  if kind == "table" then
    local parts = { }
    if value[1] ~= nil or next(value) == nil then
      for _, item in ipairs(value) do table.insert(parts, brdcJson(item)) end
      return "["..table.concat(parts, ",").."]"
    end
    for key, item in pairs(value) do table.insert(parts, brdcJsonString(key)..":"..brdcJson(item)) end
    return "{"..table.concat(parts, ",").."}"
  end
  return "null"
end

-- ---------------------------------------------------------------- Pilots

local function brdcIsPlayer(unit)
  if unit == nil then return false end
  local ok, playerName = pcall(function() return unit:getPlayerName() end)
  if not ok or playerName == nil then return false end
  local okCoalition, coalitionId = pcall(function() return unit:getCoalition() end)
  return okCoalition and coalitionId == briefingRoom.playerCoalition
end

-- Stats of the pilot flying a unit: players by name, AI wingmen of the player's groups by callsign
local function brdcPilot(unit)
  local dc = briefingRoom.dynamicCampaign
  local name = brdcSafeName(unit)
  if name == nil then return nil end
  local key = nil
  local pilotName = nil
  local ai = false
  if brdcIsPlayer(unit) then
    pilotName = unit:getPlayerName()
    key = "P:"..pilotName
  elseif dc.unitPilot[name] ~= nil then
    return dc.pilots[dc.unitPilot[name]]
  elseif dc.flight[name] ~= nil then
    local okCallsign, callsign = pcall(function() return unit:getCallsign() end)
    pilotName = (okCallsign and callsign ~= nil and callsign ~= "") and callsign or name
    key = "A:"..name
    ai = true
  else
    return nil
  end
  dc.unitPilot[name] = key
  local pilot = dc.pilots[key]
  if pilot == nil then
    pilot = {
      key = key, name = pilotName, ai = ai, aircraft = "",
      takeoffs = 0, landings = 0, flightTime = 0, airborneSince = nil, status = "OnGround",
      hitsTaken = 0, friendlyKills = 0, shotDownBy = "",
      kills = { air = 0, helicopter = 0, ground = 0, airDefense = 0, ship = 0, structure = 0 },
      weapons = { }, weaponOrder = { }
    }
    dc.pilots[key] = pilot
    table.insert(dc.pilotOrder, key)
  end
  local okType, typeName = pcall(function() return unit:getTypeName() end)
  if okType and typeName ~= nil then pilot.aircraft = typeName end
  return pilot
end

-- Every unit of the player's groups gets a debrief, even if it never fires
local function brdcTrackPilots()
  for name, _ in pairs(briefingRoom.dynamicCampaign.flight) do
    local unit = Unit.getByName(name)
    if unit ~= nil then brdcPilot(unit) end
  end
end

local function brdcEvent(pilot, kind, weapon, target)
  local dc = briefingRoom.dynamicCampaign
  if table.getn(dc.events) >= dc.MAX_EVENTS then return end
  table.insert(dc.events, { time = timer.getAbsTime(), pilot = pilot.key, kind = kind, weapon = weapon or "", target = target or "" })
end

local function brdcDisplayName(object)
  if object == nil then return nil end
  local okDesc, desc = pcall(function() return object:getDesc() end)
  if okDesc and desc ~= nil and desc.displayName ~= nil and desc.displayName ~= "" then return desc.displayName end
  local okType, typeName = pcall(function() return object:getTypeName() end)
  if okType then return typeName end
  return nil
end

-- Name and campaign category ("Gun" for shells) of a weapon object, or of the weapon name of an event
local function brdcWeaponInfo(weapon, weaponName)
  if weapon ~= nil then
    local okDesc, desc = pcall(function() return weapon:getDesc() end)
    if okDesc and desc ~= nil then
      local category = brdcWeaponCategory(desc)
      if desc.category == Weapon.Category.SHELL then category = "Gun" end
      return brdcDisplayName(weapon) or weaponName or "?", category or ""
    end
  end
  return weaponName or "?", ""
end

local function brdcWeaponStats(pilot, name, category)
  local stats = pilot.weapons[name]
  if stats == nil then
    stats = { name = name, category = category, gun = category == "Gun", shots = 0, hits = 0, kills = 0 }
    pilot.weapons[name] = stats
    table.insert(pilot.weaponOrder, name)
  end
  if stats.category == "" and category ~= "" then
    stats.category = category
    stats.gun = category == "Gun"
  end
  return stats
end

-- What a target is, taken when it is hit (a dead unit cannot be asked anymore)
local function brdcTargetInfo(object)
  local info = { name = brdcSafeName(object), display = brdcDisplayName(object) or "?", kind = "structure", friendly = false }
  local okCategory, category = pcall(function() return Object.getCategory(object) end)
  if okCategory and category == Object.Category.UNIT then
    local okDesc, desc = pcall(function() return object:getDesc() end)
    if okDesc and desc ~= nil then
      if desc.category == Unit.Category.AIRPLANE then info.kind = "air"
      elseif desc.category == Unit.Category.HELICOPTER then info.kind = "helicopter"
      elseif desc.category == Unit.Category.SHIP then info.kind = "ship"
      elseif desc.category == Unit.Category.GROUND_UNIT then
        local okAttribute, airDefense = pcall(function() return object:hasAttribute("Air Defence") end)
        info.kind = (okAttribute and airDefense) and "airDefense" or "ground"
      end
    end
  end
  local okCoalition, coalitionId = pcall(function() return object:getCoalition() end)
  info.friendly = okCoalition and coalitionId == briefingRoom.playerCoalition
  return info
end

local function brdcStopClock(pilot)
  if pilot.airborneSince ~= nil then
    pilot.flightTime = pilot.flightTime + timer.getTime() - pilot.airborneSince
    pilot.airborneSince = nil
  end
end

local function brdcCreditKill(pilot, weaponName, info)
  local dc = briefingRoom.dynamicCampaign
  if pilot == nil or info == nil then return end
  if info.name ~= nil then
    if dc.credited[info.name] then return end
    dc.credited[info.name] = true
  end
  if info.friendly then
    pilot.friendlyKills = pilot.friendlyKills + 1
    brdcEvent(pilot, "FriendlyKill", weaponName, info.display)
  else
    pilot.kills[info.kind] = (pilot.kills[info.kind] or 0) + 1
    brdcEvent(pilot, "Kill", weaponName, info.display)
  end
  if weaponName ~= nil and weaponName ~= "?" and pilot.weapons[weaponName] ~= nil then
    pilot.weapons[weaponName].kills = pilot.weapons[weaponName].kills + 1
  end
end

local function brdcDebriefJson()
  local dc = briefingRoom.dynamicCampaign
  local pilots = { }
  for _, key in ipairs(dc.pilotOrder) do
    local pilot = dc.pilots[key]
    local weapons = { }
    for _, name in ipairs(pilot.weaponOrder) do table.insert(weapons, pilot.weapons[name]) end
    local flightTime = pilot.flightTime
    if pilot.airborneSince ~= nil then flightTime = flightTime + timer.getTime() - pilot.airborneSince end
    table.insert(pilots, {
      key = pilot.key, name = pilot.name, ai = pilot.ai, aircraft = pilot.aircraft,
      takeoffs = pilot.takeoffs, landings = pilot.landings, flightTime = math.floor(flightTime), status = pilot.status,
      hitsTaken = pilot.hitsTaken, friendlyKills = pilot.friendlyKills, shotDownBy = pilot.shotDownBy,
      kills = pilot.kills, weapons = weapons
    })
  end
  local airDefenseKills = { }
  for name, sam in pairs(dc.samUnits) do
    if brdcIsDead(name) then table.insert(airDefenseKills, { x = math.floor(sam.x), y = math.floor(sam.y), radar = sam.radar }) end
  end
  return brdcJson({ pilots = pilots, events = dc.events, airDefenseKills = airDefenseKills })
end

-- ---------------------------------------------------------------- Report

local function brdcCountDead(names)
  local dead = 0
  for _, name in ipairs(names or { }) do
    if brdcIsDead(name) then dead = dead + 1 end
  end
  return dead
end

function briefingRoom.dynamicCampaign.report()
  local dc = briefingRoom.dynamicCampaign
  dc.sequence = dc.sequence + 1
  local objectivesText = { }
  for i, objective in ipairs(briefingRoom.mission.objectives) do
    local units = dc.objectiveUnits[i] or { }
    local site = dc.siteUnits[i] or { }
    local complete = 0
    if objective.complete and not objective.failed then complete = 1 end
    table.insert(objectivesText, brdcCountDead(units).."/"..table.getn(units).."/"..complete.."/"..brdcCountDead(site).."/"..table.getn(site))
  end
  local missionComplete = 0
  if briefingRoom.mission.complete then missionComplete = 1 end
  env.info("BRDC|"..dc.token.."|"..dc.sequence.."|"..string.format("%.0f", timer.getTime()).."|"..missionComplete.."|"..dc.playerLostCount.."|"..table.concat(objectivesText, ",")..brdcFlightText(), false)
  local ok, debrief = pcall(brdcDebriefJson)
  if ok then env.info("BRDCS|"..dc.token.."|"..dc.sequence.."|"..debrief, false) end
end

-- Player aircraft and AI wingmen of the player's groups
local function brdcMarkPlayerLost(unit)
  local name = brdcSafeName(unit)
  if name == nil then return end
  if not brdcIsPlayer(unit) and briefingRoom.dynamicCampaign.flight[name] == nil then return end
  if briefingRoom.dynamicCampaign.playerLost[name] then return end
  briefingRoom.dynamicCampaign.playerLost[name] = true
  briefingRoom.dynamicCampaign.playerLostCount = briefingRoom.dynamicCampaign.playerLostCount + 1
end

-- ---------------------------------------------------------------- Events

local function brdcDebriefEvent(event)
  local dc = briefingRoom.dynamicCampaign
  if event.id == world.event.S_EVENT_SHOT then
    local pilot = brdcPilot(event.initiator)
    if pilot == nil then return end
    local weaponName, category = brdcWeaponInfo(event.weapon, event.weapon_name)
    local stats = brdcWeaponStats(pilot, weaponName, category)
    stats.shots = stats.shots + 1
    local target = nil
    if event.weapon ~= nil then
      local okTarget, weaponTarget = pcall(function() return event.weapon:getTarget() end)
      if okTarget and weaponTarget ~= nil then target = brdcDisplayName(weaponTarget) end
    end
    brdcEvent(pilot, "Shot", weaponName, target)

  elseif event.id == world.event.S_EVENT_HIT then
    local victim = brdcPilot(event.target)
    if victim ~= nil then victim.hitsTaken = victim.hitsTaken + 1 end
    local pilot = brdcPilot(event.initiator)
    if pilot == nil or event.target == nil then return end
    local weaponName, category = brdcWeaponInfo(event.weapon, event.weapon_name)
    if event.weapon == nil then category = "Gun" end -- shells come without a weapon object
    local stats = brdcWeaponStats(pilot, weaponName, category)
    -- A missile or bomb is one hit even if it damages several units; every shell counts
    local weaponId = nil
    if event.weapon ~= nil and not stats.gun then weaponId = event.weapon.id_ end
    if weaponId == nil or not dc.hitWeapons[weaponId] then
      stats.hits = stats.hits + 1
      if weaponId ~= nil then dc.hitWeapons[weaponId] = true end
    end
    local info = brdcTargetInfo(event.target)
    if info.name ~= nil then dc.lastHit[info.name] = { pilot = pilot.key, weapon = weaponName, target = info } end

  elseif event.id == world.event.S_EVENT_KILL then
    local victim = brdcPilot(event.target)
    local pilot = brdcPilot(event.initiator)
    local weaponName = brdcWeaponInfo(event.weapon, event.weapon_name)
    if victim ~= nil and pilot == nil then
      local killer = brdcDisplayName(event.initiator) or "?"
      victim.shotDownBy = killer
      brdcEvent(victim, "ShotDown", weaponName, killer)
    end
    if pilot ~= nil and event.target ~= nil then
      local targetName = brdcSafeName(event.target)
      local hit = targetName ~= nil and dc.lastHit[targetName] or nil
      if hit ~= nil and hit.pilot == pilot.key then
        -- Same weapon name as the hit/shot events (kill events may only have the internal name)
        brdcCreditKill(pilot, hit.weapon, hit.target)
      else
        brdcCreditKill(pilot, weaponName, hit ~= nil and hit.target or brdcTargetInfo(event.target))
      end
    end

  elseif event.id == world.event.S_EVENT_DEAD or event.id == world.event.S_EVENT_UNIT_LOST or event.id == world.event.S_EVENT_CRASH then
    -- Destroyed without a kill event: credit the last pilot who hit it
    local name = brdcSafeName(event.initiator)
    local hit = name ~= nil and dc.lastHit[name] or nil
    if hit ~= nil then brdcCreditKill(dc.pilots[hit.pilot], hit.weapon, hit.target) end
    if event.id == world.event.S_EVENT_CRASH then
      local pilot = brdcPilot(event.initiator)
      if pilot ~= nil then
        brdcStopClock(pilot)
        if pilot.status ~= "Ejected" and pilot.status ~= "Killed" then
          pilot.status = "Lost"
          brdcEvent(pilot, "Lost")
        end
      end
    end

  elseif event.id == world.event.S_EVENT_TAKEOFF then
    local pilot = brdcPilot(event.initiator)
    if pilot == nil then return end
    pilot.takeoffs = pilot.takeoffs + 1
    pilot.airborneSince = timer.getTime()
    pilot.status = "Airborne"
    brdcEvent(pilot, "Takeoff", nil, brdcSafeName(event.place))

  elseif event.id == world.event.S_EVENT_LAND then
    local pilot = brdcPilot(event.initiator)
    if pilot == nil or pilot.airborneSince == nil then return end
    brdcStopClock(pilot)
    pilot.landings = pilot.landings + 1
    pilot.status = "Landed"
    brdcEvent(pilot, "Landing", nil, brdcSafeName(event.place))

  elseif event.id == world.event.S_EVENT_EJECTION then
    local pilot = brdcPilot(event.initiator)
    if pilot == nil then return end
    brdcStopClock(pilot)
    if pilot.status ~= "Killed" then pilot.status = "Ejected" end
    brdcEvent(pilot, "Ejected")

  elseif event.id == world.event.S_EVENT_PILOT_DEAD then
    local pilot = brdcPilot(event.initiator)
    if pilot == nil then return end
    brdcStopClock(pilot)
    pilot.status = "Killed"
    brdcEvent(pilot, "Killed")
  end
end

briefingRoom.dynamicCampaign.eventHandler = { }
function briefingRoom.dynamicCampaign.eventHandler:onEvent(event)
  if event == nil then return end
  if event.id == world.event.S_EVENT_DEAD or event.id == world.event.S_EVENT_CRASH or event.id == world.event.S_EVENT_UNIT_LOST then
    local name = brdcSafeName(event.initiator)
    if name ~= nil then briefingRoom.dynamicCampaign.dead[name] = true end
  end
  if event.id == world.event.S_EVENT_KILL then
    local name = brdcSafeName(event.target)
    if name ~= nil then briefingRoom.dynamicCampaign.dead[name] = true end
  end
  if event.id == world.event.S_EVENT_CRASH or event.id == world.event.S_EVENT_EJECTION or event.id == world.event.S_EVENT_PILOT_DEAD then
    brdcMarkPlayerLost(event.initiator)
  end
  if event.id == world.event.S_EVENT_BIRTH and brdcIsPlayer(event.initiator) then
    brdcTrackFlight(event.initiator, false)
    brdcPilot(event.initiator)
    brdcTrackPilots()
    local okAir, inAir = pcall(function() return event.initiator:inAir() end)
    if okAir and inAir then -- air start: no takeoff event
      brdcCheckStock()
      local pilot = brdcPilot(event.initiator)
      if pilot ~= nil and pilot.airborneSince == nil then
        pilot.airborneSince = timer.getTime()
        pilot.status = "Airborne"
      end
    end
  end
  if event.id == world.event.S_EVENT_TAKEOFF and brdcIsPlayer(event.initiator) then
    local name = brdcSafeName(event.initiator)
    -- Loadout as it was at the first takeoff (after any rearming on the ground)
    if name ~= nil and not briefingRoom.dynamicCampaign.tookOff[name] then
      briefingRoom.dynamicCampaign.tookOff[name] = true
      brdcTrackFlight(event.initiator, true)
      brdcCheckStock()
    end
  end
  local ok, err = pcall(brdcDebriefEvent, event)
  if not ok then env.info("BRDC debrief error: "..tostring(err), false) end
  if event.id == world.event.S_EVENT_MISSION_END then
    briefingRoom.dynamicCampaign.report()
  end
end

-- ---------------------------------------------------------------- Start

local function brdcIsRadar(unit)
  local ok, radar = pcall(function() return unit:hasAttribute("SAM SR") or unit:hasAttribute("SAM TR") end)
  return ok and radar
end

-- The campaign target is the first objective. A SAM site whose radars were destroyed
-- in an earlier mission is spawned without them: they are not rebuilt yet.
local function brdcRemoveDestroyedRadars()
  local dc = briefingRoom.dynamicCampaign
  local objective = briefingRoom.mission.objectives[1]
  if not dc.radarsDown or objective == nil then return end
  local names = { }
  for _, name in ipairs(objective.unitNames or { }) do table.insert(names, name) end
  for _, name in ipairs(names) do
    local unit = Unit.getByName(name)
    if unit ~= nil and brdcIsRadar(unit) then
      dc.removed[name] = true
      briefingRoom.mission.objectivesTriggersCommon.removeObjectiveUnitName(1, name)
      pcall(function() unit:destroy() end)
    end
  end
  objective.unitsCount = table.getn(objective.unitNames)
end

local function brdcTrackObjectives()
  local dc = briefingRoom.dynamicCampaign
  for i, objective in ipairs(briefingRoom.mission.objectives) do
    dc.objectiveUnits[i] = { }
    dc.siteUnits[i] = { }
    for _, name in ipairs(objective.unitNames or { }) do
      if brdcFindObject(name) ~= nil then
        dc.tracked[name] = true
        table.insert(dc.objectiveUnits[i], name)
      end
    end
    for _, name in ipairs(dc.objectiveUnits[i]) do
      local unit = Unit.getByName(name)
      local okGroup, group = pcall(function() return unit:getGroup() end)
      local groupUnits = (unit ~= nil and okGroup and group ~= nil) and (group:getUnits() or { }) or { }
      if table.getn(groupUnits) == 0 then groupUnits = { unit or StaticObject.getByName(name) } end
      for _, groupUnit in ipairs(groupUnits) do
        local unitName = brdcSafeName(groupUnit)
        if unitName ~= nil and not dc.siteNames[unitName] and not dc.removed[unitName] then
          dc.siteNames[unitName] = true
          table.insert(dc.siteUnits[i], unitName)
        end
      end
    end
  end
end

-- Medium and long range SAM units around the target, reported when destroyed so they hurt
-- the campaign SAM site they belong to
local function brdcTrackAirDefenses()
  local dc = briefingRoom.dynamicCampaign
  local enemyCoalition = 3 - briefingRoom.playerCoalition
  local okGroups, groups = pcall(function() return coalition.getGroups(enemyCoalition, Group.Category.GROUND) end)
  if not okGroups or groups == nil then return end
  for _, group in ipairs(groups) do
    for _, unit in ipairs(group:getUnits() or { }) do
      local name = brdcSafeName(unit)
      if name ~= nil and not dc.siteNames[name] and not dc.removed[name] then
        local okSam, sam = pcall(function() return unit:hasAttribute("MR SAM") or unit:hasAttribute("LR SAM") end)
        if okSam and sam then
          local point = unit:getPoint()
          dc.samUnits[name] = { x = point.x, y = point.z, radar = brdcIsRadar(unit) }
        end
      end
    end
  end
end

function briefingRoom.dynamicCampaign.start()
  local dc = briefingRoom.dynamicCampaign
  pcall(brdcRemoveDestroyedRadars)
  brdcTrackObjectives()
  pcall(brdcTrackAirDefenses)

  -- Players already in their aircraft when the mission started
  local okPlayers, players = pcall(function() return coalition.getPlayers(briefingRoom.playerCoalition) end)
  if okPlayers and players ~= nil then
    for _, unit in ipairs(players) do
      brdcTrackFlight(unit, false)
      brdcPilot(unit)
    end
  end
  brdcTrackPilots()

  -- End mission available at any time (the result is reported when the mission ends),
  -- instead of the root menu command added only when every objective is complete
  briefingRoom.mission.commandEnd = false
  missionCommands.addCommandForCoalition(briefingRoom.playerCoalition, dc.endMissionLabel, briefingRoom.f10Menu.missionMenu, briefingRoom.f10MenuCommands.endMission, nil)

  -- Report again whenever an objective is completed
  local completeObjective = briefingRoom.mission.coreFunctions.completeObjective
  briefingRoom.mission.coreFunctions.completeObjective = function(index, failed)
    completeObjective(index, failed)
    pcall(briefingRoom.dynamicCampaign.report)
  end

  dc.report()
  timer.scheduleFunction(function(_, time)
    pcall(briefingRoom.dynamicCampaign.report)
    return time + 60
  end, nil, timer.getTime() + 60)
end

world.addEventHandler(briefingRoom.dynamicCampaign.eventHandler)
timer.scheduleFunction(function() briefingRoom.dynamicCampaign.start() end, nil, timer.getTime() + 2)
